222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
225	        Owner owner = this.clinicService.findOwnerById(ownerId);
226	        if (owner != null) {
227	            Pet pet = owner.getPet(petId);
228	            if (pet != null) {
229	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
230	            }
231	        }
232	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	    }
234	
235	    /**
236	     * Create and persist a brand-new owner from the supplied fields, returning the
237	     * {@code 201 Created} response for it. This gathers the whole create pipeline in one
238	     * place — map the fields, {@link #normalizeNewOwner normalise} them, apply the daily,
239	     * city and household gates (each with its own rejection status), resolve any household,
240	     * {@link #assignDerivedAttributes derive the create-time attributes}, save, audit and
241	     * build the response with its {@code Location} header — so {@link #addOwner} itself
242	     * stays a thin entry point.
243	     *
244	     * @param ownerFieldsDto the owner fields from the request body
245	     * @return {@code 201 Created} with the created owner and its {@code Location} header,
246	     *         or the appropriate rejection status: {@code 400 Bad Request} when the fields
247	     *         are invalid, {@code 429 Too Many Requests} when the day's create cap is
248	     *         reached, or {@code 409 Conflict} when the city is at capacity or the owner
249	     *         joins an existing household without declaring {@code sharesHousehold}
250	     */
251	    private ResponseEntity<OwnerDto> createNewOwner(OwnerFieldsDto ownerFieldsDto) {
252	        HttpHeaders headers = new HttpHeaders();
253	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
254	        if (!normalizeNewOwner(owner)) {
255	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
256	        }
257	        if (dailyLimitReached(owner.getRegistrationDate())) {
258	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
259	        }
260	        if (cityIsAtCapacity(owner.getCity())) {
261	            return new ResponseEntity<>(HttpStatus.CONFLICT);
262	        }
263	        owner.setHouseholdId(owner.computeHouseholdId());
264	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
265	        boolean joinsExistingHousehold = !findHouseholdMembers(owner).isEmpty();
266	        if (joinsExistingHousehold && !sharesHousehold) {
267	            return new ResponseEntity<>(HttpStatus.CONFLICT);
268	        }
269	        boolean declaredHouseholdMember = joinsExistingHousehold;
270	        assignDerivedAttributes(owner, declaredHouseholdMember);
271	        this.clinicService.saveOwner(owner);
272	        auditOwnerCreated(owner);
273	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
274	        headers.setLocation(UriComponentsBuilder.newInstance()
275	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
276	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
277	    }
278	
279	    /**
280	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
281	     * the canonical form each stored value must take: the address is trimmed,
282	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
283	     * telephone is converted to E.164, any email is lower-cased and a missing
284	     * registration date defaults to today. Field-level rejections are reported here
285	     * rather than inline in {@link #addOwner}, and normalisation runs before any
286	     * household comparison so those comparisons see the canonical values.
287	     *
288	     * @param owner the freshly-mapped owner to normalise
289	     * @return {@code true} if the fields are valid, or {@code false} if the address
290	     *         is blank after normalisation, the telephone cannot form a valid
291	     *         E.164 number, or a supplied registration date is later than the
292	     *         server date, in which case the request must be rejected with
293	     *         {@code 400 Bad Request}
294	     */
295	    private boolean normalizeNewOwner(Owner owner) {
296	        if (!normalizeAddressFields(owner)) {
297	            return false;
298	        }
299	        String telephone = Telephones.toE164(owner.getTelephone());
300	        if (telephone == null) {
301	            return false;
302	        }
303	        owner.setTelephone(telephone);
304	        if (owner.getEmail() != null) {
305	            String email = owner.getEmail().toLowerCase();
306	            owner.setEmail(email);
307	            if (emailDomainIsBlocked(email)) {
308	                return false;
309	            }
310	        }
311	        if (!owner.postcodeValidForLocality()) {
312	            return false;
313	        }
314	        if (owner.getRegistrationDate() == null) {
315	            owner.setRegistrationDate(LocalDate.now());
316	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
317	            return false;
318	        }
319	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
320	        return true;
321	    }
322	
323	    /**
324	     * Normalise the owner's address fields in place to their canonical stored form
325	     * (trimmed, whitespace-collapsed, upper-cased and with common abbreviations
326	     * expanded; see {@link Owner#normalizeAddress(String)}), gathering the whole address
327	     * concern of {@link #normalizeNewOwner} in one place. The structured form is
328	     * preferred: when a non-blank {@code addressLine1} is supplied it (and any
329	     * {@code addressLine2}) is normalised, and the flat {@code address} is composed from
330	     * them — the normalised {@code addressLine1}, with a single space and the normalised
331	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the
332	     * flat {@code address} is normalised on its own, preserving backward compatibility.
333	     * Either way the canonicalised values are written back so every later household
334	     * comparison and read sees them.
335	     *
336	     * @param owner the freshly-mapped owner whose address fields are being normalised
337	     * @return {@code true} once an address is valid and stored, or {@code false} when
338	     *         neither a structured {@code addressLine1} nor a flat {@code address} is
339	     *         present after normalisation, in which case the request must be rejected
340	     *         with {@code 400 Bad Request}
341	     */
342	    private boolean normalizeAddressFields(Owner owner) {
343	        String addressLine1 = Owner.normalizeAddress(owner.getAddressLine1());
344	        if (!addressLine1.isEmpty()) {
345	            owner.setAddressLine1(addressLine1);
346	            String composed = addressLine1;
347	            String addressLine2 = Owner.normalizeAddress(owner.getAddressLine2());
348	            if (!addressLine2.isEmpty()) {
349	                owner.setAddressLine2(addressLine2);
350	                composed = addressLine1 + " " + addressLine2;
351	            }
352	            owner.setAddress(composed);
353	            return true;
354	        }
355	        String address = Owner.normalizeAddress(owner.getAddress());
356	        if (address.isEmpty()) {
357	            return false;
358	        }
359	        owner.setAddress(address);
360	        return true;
361	    }
362	
363	    /**
364	     * Email domains that identify disposable, throw-away mailboxes. An owner whose
365	     * email address is on one of these domains is rejected with {@code 400 Bad
366	     * Request} rather than created.
367	     */
368	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
369	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
370	
371	    /**
372	     * Whether the given (already lower-cased) email address belongs to a disposable
373	     * mailbox domain on the blocklist. The domain is the part after the final
374	     * {@code '@'}; an address without one is treated as having no blocked domain.
375	     *
376	     * @param email the owner's normalised (lower-cased) email address
377	     * @return {@code true} if the email's domain is on the disposable-domain blocklist
378	     */
379	    private static boolean emailDomainIsBlocked(String email) {
380	        int at = email.lastIndexOf('@');
381	        if (at < 0) {
382	            return false;
383	        }
384	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
385	    }
386	
387	    /**
388	     * The fixed list of public holidays on which the clinic is closed. A registration
389	     * date that lands on one of these dates is treated the same as a weekend and rolled
390	     * forward past it (see {@link #rollToBusinessDay(LocalDate)}).
391	     */
392	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
393	        LocalDate.of(2026, 1, 1),
394	        LocalDate.of(2026, 1, 26),
395	        LocalDate.of(2026, 4, 25),
396	        LocalDate.of(2026, 12, 25),
397	        LocalDate.of(2026, 12, 28));
398	
399	    /**
400	     * Roll the given date forward to the next business day when it falls on a weekend or
401	     * a listed public holiday: a Saturday, Sunday or public holiday is advanced one day
402	     * at a time until a non-holiday weekday is reached, while a plain business day is
403	     * returned unchanged. Because rolling off a weekend can land on a holiday (and vice
404	     * versa), the advance repeats until the date is neither. Applied to the effective
405	     * registration date (whether supplied in the request or defaulted to the server date)
406	     * so that every value derived from it uses the adjusted business day.
407	     *
408	     * @param date the effective registration date
409	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
410	     */
411	    private static LocalDate rollToBusinessDay(LocalDate date) {
412	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
413	            date = date.plusDays(1);
414	        }
415	        return date;
416	    }
417	
418	    /**
419	     * Whether the given date falls on a weekend (Saturday or Sunday).
420	     */
421	    private static boolean isWeekend(LocalDate date) {
422	        return switch (date.getDayOfWeek()) {
423	            case SATURDAY, SUNDAY -> true;
424	            default -> false;
425	        };
426	    }
427	
428	    /**
429	     * Find the existing owners that belong to the same household as the given owner,
430	     * i.e. share the same last name (compared case-insensitively with runs of
431	     * whitespace collapsed to a single space) and postcode, and so resolve to the same
432	     * deterministic {@code householdId}. Soft-deleted owners are excluded, so the result
433	     * holds only current household members. Evaluated before the new owner is saved, so
434	     * it reflects only owners that already existed at creation time; an owner joining no
435	     * existing household yields an empty list.
436	     *
437	     * @param owner the candidate owner being created
438	     * @return the current members of the owner's household, empty if none exists
439	     */
440	    private List<Owner> findHouseholdMembers(Owner owner) {
441	        return this.clinicService.findAllOwners().stream()
442	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()))
443	            .filter(existing -> existing.sameHouseholdAs(owner))
444	            .toList();
445	    }
446	
447	    /**
448	     * Assign the owner's computed-at-creation attributes in place: its customer code,
449	     * namesake count, membership number, bulk-signup warning and household size. Unlike
450	     * the {@code @Transient} attributes {@link Owner} recomputes on demand, these are
451	     * derived once here — from the owner's own (already normalised) fields and from the
452	     * wider owner population — and persisted with the owner. Run after normalisation,
453	     * household resolution and the identity-key check, so every value reflects the
454	     * owner's final field values and any household it has joined, and immediately before
455	     * the owner is saved.
456	     *
457	     * <p>Ordering matters: the customer code is assigned first because the membership
458	     * number is built from it.
459	     *
460	     * @param owner the candidate owner being created, after household resolution
461	     * @param declaredHouseholdMember whether this owner was created as a declared member
462	     *                                of an existing household (it shared an existing
463	     *                                owner's household and set {@code sharesHousehold}),
464	     *                                in which case it is not a suspected duplicate
465	     */
466	    private void assignDerivedAttributes(Owner owner, boolean declaredHouseholdMember) {
467	        owner.setCustomerCode(deduplicatedCustomerCode(owner));
468	        owner.setNamesakeCount(countNamesakes(owner));
469	        owner.setMembershipNumber(owner.computeMembershipNumber());
470	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
471	        owner.setHouseholdSize(householdSize(owner));
472	        assignPossibleDuplicate(owner, declaredHouseholdMember);
473	    }
474	
475	    /**
476	     * Compute the customer code to assign to the candidate owner, de-duplicated against
477	     * every existing owner's customer code. The base code is the owner's computed
478	     * {@code <REGION>-<HASH8>} (see {@link Owner#computeCustomerCode()}); when it does not
479	     * already belong to an existing owner it is used unchanged. Otherwise it collides, and
480	     * {@code -<n>} is appended with the smallest integer {@code n} of 2 or more that yields
481	     * a code no existing owner holds, so the returned customer code is unique. Evaluated
482	     * before the owner is saved, so only pre-existing owners are considered.
483	     *
484	     * @param owner the candidate owner being created, after normalisation
485	     * @return the unique (de-duplicated) customer code to assign
486	     */
487	    private String deduplicatedCustomerCode(Owner owner) {
488	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
489	            .map(Owner::getCustomerCode)
490	            .filter(code -> code != null)
491	            .collect(java.util.stream.Collectors.toSet());
492	        String base = owner.computeCustomerCode();
493	        if (!existingCodes.contains(base)) {
494	            return base;
495	        }
496	        int n = 2;
497	        while (existingCodes.contains(base + "-" + n)) {
498	            n++;
499	        }
500	        return base + "-" + n;
501	    }
502	
503	    /**
504	     * Flag the candidate owner as a possible duplicate of an existing owner. A soft
505	     * match is an existing owner that shares this owner's last name (compared
506	     * case-insensitively) and postcode but carries a different (normalised) telephone.
507	     * When such a match exists the owner is still created, but with
508	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the matching
509	     * owner's id; otherwise {@code possibleDuplicate} is false and no match id is
510	     * recorded. The earliest-created matching owner (lowest id) is chosen so the result
511	     * is deterministic. Evaluated before the owner is saved, so only pre-existing owners
512	     * are considered.
513	     *
514	     * <p>A declared household member — one that shared an existing owner's household
515	     * (same last name and postcode) and was admitted because it set
516	     * {@code sharesHousehold} — is never flagged: a declared member is not a suspected
517	     * duplicate, so its {@code possibleDuplicate} is false with no match id.
518	     *
519	     * @param owner the candidate owner being created, after household resolution
520	     * @param declaredHouseholdMember whether the owner is a declared household member
521	     */
522	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
523	        if (declaredHouseholdMember) {
524	            owner.setPossibleDuplicate(false);
525	            owner.setPossibleDuplicateOf(null);
526	            return;
527	        }
528	        String lastName = normalizeName(owner.getLastName());
529	        String postcode = owner.getPostcode();
530	        String telephone = owner.getTelephone();
531	        Optional<Owner> match = this.clinicService.findAllOwners().stream()
532	            .filter(existing -> postcode != null && postcode.equals(existing.getPostcode())
533	                && normalizeName(existing.getLastName()).equals(lastName)
534	                && telephone != null && !telephone.equals(existing.getTelephone()))
535	            .min(Comparator.comparing(Owner::getId));
536	        if (match.isPresent()) {
537	            owner.setPossibleDuplicate(true);
538	            owner.setPossibleDuplicateOf(match.get().getId());
539	        } else {
540	            owner.setPossibleDuplicate(false);
541	            owner.setPossibleDuplicateOf(null);
542	        }
543	    }
544	
545	    /**
546	     * Count how many owners belong to the given owner's household once this create
547	     * completes: the owners that already share its deterministic {@code householdId}
548	     * (derived from last name and postcode) plus the owner being created. Evaluated
549	     * after the owner's {@code householdId} has been assigned. An owner whose
550	     * {@code householdId} matches no existing owner is a household of one.
551	     *
552	     * @param owner the candidate owner being created, after household resolution
553	     * @return the household member count after this create (at least {@code 1})
554	     */
555	    private int householdSize(Owner owner) {
556	        String householdId = owner.getHouseholdId();
557	        if (householdId == null) {
558	            return 1;
559	        }
560	        long existing = this.clinicService.findAllOwners().stream()
561	            .filter(other -> householdId.equals(other.getHouseholdId()))
562	            .count();
563	        return (int) existing + 1;
564	    }
565	
566	    /**
567	     * Count the existing owners that share the given owner's first and last name,
568	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
569	     * before the new owner is saved, so the result reflects only owners that
570	     * already existed at creation time.
571	     *
572	     * @param owner the candidate owner being created
573	     * @return the number of existing namesakes
574	     */
575	    private int countNamesakes(Owner owner) {
576	        String firstName = normalizeName(owner.getFirstName());
577	        String lastName = normalizeName(owner.getLastName());
578	        return (int) this.clinicService.findAllOwners().stream()
579	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
580	                && normalizeName(existing.getLastName()).equals(lastName))
581	            .count();
582	    }
583	
584	    private static String normalizeName(String value) {
585	        return value == null ? "" : value.trim().toLowerCase();
586	    }
587	
588	    /**
589	     * Determine whether the given city has already reached its owner capacity, i.e.
590	     * it already contains 50 or more existing owners (compared case-insensitively
591	     * with surrounding whitespace trimmed). A new owner may not be created in a city
592	     * that is at capacity.
593	     *
594	     * @param city the candidate owner's city
595	     * @return {@code true} if the city already holds 50 or more owners
596	     */
597	    private boolean cityIsAtCapacity(String city) {
598	        String normalizedCity = normalizeName(city);
599	        long count = this.clinicService.findAllOwners().stream()
600	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
601	            .count();
602	        return count >= 50;
603	    }
604	
605	    /**
606	     * Determine whether the daily owner-creation limit has already been reached, i.e.
607	     * 100 or more owners already carry the given registration date. A new owner may
608	     * not be created once that day's cap is reached.
609	     *
610	     * @param registrationDate the registration date the new owner would be created with
611	     * @return {@code true} if 100 or more existing owners share that registration date
612	     */
613	    private boolean dailyLimitReached(LocalDate registrationDate) {
614	        long count = this.clinicService.findAllOwners().stream()
615	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
616	            .count();
617	        return count >= 100;
618	    }
619	
620	    /**
621	     * Determine whether more than 80 owners have already been created for the given
622	     * registration date, i.e. strictly more than 80 existing owners carry that date.
623	     * Evaluated before the new owner is saved, so it reflects only owners that
624	     * already existed at creation time.
625	     *
626	     * @param registrationDate the registration date the new owner would be created with
627	     * @return {@code true} if more than 80 existing owners share that registration date
628	     */
629	    private boolean bulkSignupWarning(LocalDate registrationDate) {
630	        long count = this.clinicService.findAllOwners().stream()
631	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
632	            .count();
633	        return count > 80;
634	    }
635	
636	    /**
637	     * Write the create audit record for a freshly-saved owner. Keeps the audit format in
638	     * one place so it stays in step with the owner's identity: it reports the assigned
639	     * customer code alongside the owner's id, registration date, membership level and
640	     * membership number.
641	     *
642	     * @param owner the owner that has just been created and saved
643	     */
644	    private void auditOwnerCreated(Owner owner) {
645	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
646	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
647	            owner.getMembershipNumber());
648	    }
649	}
